rule.query:
{
  "selection_lastlog": {
    "Image|endswith": [
      "/lastlog",
      "/last",
      "/lastb"
    ]
  },
  "selection_root_string": {
    "CommandLine|contains": "x:0:"
  },
  "selection_read_utilities": {
    "Image|endswith": [
      "/cat",
      "/ed",
      "/emacs",
      "/head",
      "/less",
      "/makemap",
      "/more",
      "/nano",
      "/sqlite3",
      "/tail",
      "/vi",
      "/vim"
    ],
    "CommandLine|contains": [
      "/etc/passwd",
      "/etc/shadow",
      "/etc/sudoers",
      "master.passwd",
      "pwd.db"
    ]
  },
  "selection_id": {
    "Image|endswith": "/id"
  },
  "selection_lsof": {
    "Image|endswith": "/lsof",
    "CommandLine|contains": "-u"
  },
  "selection_getent": {
    "Image|endswith": "/getent",
    "CommandLine|contains": [
      " passwd",
      " shadow"
    ]
  },
  "selection_who": {
    "Image|endswith": [
      "/finger",
      "/users",
      "/w",
      "/who"
    ]
  },
  "selection_ypcat": {
    "Image|endswith": "/ypcat",
    "CommandLine|contains": "passwd"
  },
  "filter_optional_landscape_sysinfo": {
    "ParentCommandLine|contains": "/usr/bin/landscape-sysinfo",
    "Image|endswith": "/who"
  },
  "condition": "1 of selection_* and not 1 of filter_optional_*"
}
